```javascript
const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const N = Number(input[0]);
const F = Number(input[1]);

const grid = [];
for (let i = 0; i < N; i++) {
  grid.push(input[2 + i].split(''));
}

const startValue = grid[0][0].charCodeAt(0) - 48;

if (startValue <= F) {
  grid[0][0] = '*';

  const total = N * N;
  const queue = new Int32Array(total);
  let head = 0;
  let tail = 0;

  queue[tail++] = 0;

  while (head < tail) {
    const idx = queue[head++];
    const r = Math.floor(idx / N);
    const c = idx - r * N;

    if (r > 0) {
      const ch = grid[r - 1][c];
      if (ch !== '*' && ch.charCodeAt(0) - 48 <= F) {
        grid[r - 1][c] = '*';
        queue[tail++] = idx - N;
      }
    }

    if (r + 1 < N) {
      const ch = grid[r + 1][c];
      if (ch !== '*' && ch.charCodeAt(0) - 48 <= F) {
        grid[r + 1][c] = '*';
        queue[tail++] = idx + N;
      }
    }

    if (c > 0) {
      const ch = grid[r][c - 1];
      if (ch !== '*' && ch.charCodeAt(0) - 48 <= F) {
        grid[r][c - 1] = '*';
        queue[tail++] = idx - 1;
      }
    }

    if (c + 1 < N) {
      const ch = grid[r][c + 1];
      if (ch !== '*' && ch.charCodeAt(0) - 48 <= F) {
        grid[r][c + 1] = '*';
        queue[tail++] = idx + 1;
      }
    }
  }
}

process.stdout.write(grid.map(row => row.join('')).join('\n'));
